class Solution {
    vector<int> distances(vector<int>& e,int start){
        vector<int> d(e.size(),-1);int step=0;
        while(start!=-1 && d[start]==-1){d[start]=step++;start=e[start];}
        return d;
    }
public:
    int closestMeetingNode(vector<int>& edges,int node1,int node2) {
        auto a=distances(edges,node1),b=distances(edges,node2);
        int ans=-1,best=INT_MAX;
        for(int i=0;i<(int)edges.size();++i)if(a[i]>=0&&b[i]>=0){
            int x=max(a[i],b[i]);if(x<best){best=x;ans=i;}
        }
        return ans;
    }
};
